t.script:
                    document.addEventListener("DOMContentLoaded", function () {

                        const manualRadio = document.getElementById("o_manual_payment");
                        const manualSection = document.getElementById("o_manual_payment_fields");
                        const payNowBtn = document.querySelector('button[name="o_payment_submit_button"]');
                        const radios = document.querySelectorAll('input[name="o_payment_radio"]');

                        /* Show / Hide Logic */
                        function showManual() {
                            manualSection.style.display = "block";
                            if (payNowBtn) payNowBtn.disabled = true;
                        }
                        function hideManual() {
                            manualSection.style.display = "none";
                            if (payNowBtn) payNowBtn.disabled = false;
                        }

                        radios.forEach(r => {
                            r.addEventListener("change", function () {
                                manualRadio.checked ? showManual() : hideManual();
                            });
                        });

                        hideManual();

                        /* ======================= FILE UPLOAD ======================= */
                        const btn = document.getElementById("manual_submit_btn");
                        const msg = document.getElementById("manual_upload_msg");

                        btn.addEventListener("click", async function () {

                            const fileInput = document.getElementById("upload_proof");
                            const leadId = document.getElementById("lead_id").value;

                            if (!fileInput.files.length) {
                                alert("Please upload a file.");
                                return;
                            }

                            let formData = new FormData();
                            formData.append("lead_id", leadId);
                            formData.append("upload_proof", fileInput.files[0]);

                            const response = await fetch("/manual/payment/submit?db=odoo", {
                                method: "POST",
                                body: formData,
				credentials: "same-origin"
                            });

                            if (response.redirected) {
                                msg.style.display = "block";
                                window.location.href = response.url;
                            }
                        });

                    });
